
/* =====================================
   MEU BLOG - JAVASCRIPT
      Funções e interatividade do site
      ===================================== */

      // 1. Mensagem de boas-vindas
      function mostrarMensagem() {
          alert("🎉 Bem-vindo ao Meu Blog! Obrigado pela visita!");
          }

          // 2. Mostrar a data atual
          function mostrarData() {
              const elemento = document.getElementById("data-atual");

                  if (elemento) {
                          const agora = new Date();

                                  elemento.textContent = agora.toLocaleDateString("pt-BR", {
                                              weekday: "long",
                                                          year: "numeric",
                                                                      month: "long",
                                                                                  day: "numeric"
                                                                                          });
                                                                                              }
                                                                                              }

                                                                                              // 3. Atualizar o relógio
                                                                                              function atualizarRelogio() {
                                                                                                  const relogio = document.getElementById("relogio");

                                                                                                      if (relogio) {
                                                                                                              relogio.textContent = new Date().toLocaleTimeString("pt-BR");
                                                                                                                  }
                                                                                                                  }

                                                                                                                  // 4. Alternar entre modo claro e escuro
                                                                                                                  function alternarTema() {
                                                                                                                      document.body.classList.toggle("modo-escuro");

                                                                                                                          const escuro = document.body.classList.contains("modo-escuro");

                                                                                                                              localStorage.setItem("temaBlog", escuro ? "escuro" : "claro");
                                                                                                                              }

                                                                                                                              // 5. Carregar o tema salvo
                                                                                                                              function carregarTema() {
                                                                                                                                  const tema = localStorage.getItem("temaBlog");

                                                                                                                                      if (tema === "escuro") {
                                                                                                                                              document.body.classList.add("modo-escuro");
                                                                                                                                                  }
                                                                                                                                                  }

                                                                                                                                                  // 6. Pesquisar artigos no blog
                                                                                                                                                  function pesquisarArtigos() {
                                                                                                                                                      const campo = document.getElementById("pesquisa");

                                                                                                                                                          if (!campo) return;

                                                                                                                                                              const termo = campo.value.toLowerCase().trim();
                                                                                                                                                                  const artigos = document.querySelectorAll("article");

                                                                                                                                                                      artigos.forEach(function(artigo) {
                                                                                                                                                                              const conteudo = artigo.textContent.toLowerCase();

                                                                                                                                                                                      artigo.style.display =
                                                                                                                                                                                                  conteudo.includes(termo) ? "" : "none";
                                                                                                                                                                                                      });
                                                                                                                                                                                                      }

                                                                                                                                                                                                      // 7. Limpar pesquisa
                                                                                                                                                                                                      function limparPesquisa() {
                                                                                                                                                                                                          const campo = document.getElementById("pesquisa");

                                                                                                                                                                                                              if (campo) {
                                                                                                                                                                                                                      campo.value = "";
                                                                                                                                                                                                                              pesquisarArtigos();
                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                  // 8. Curtir um artigo
                                                                                                                                                                                                                                  function curtirArtigo(botao) {
                                                                                                                                                                                                                                      const artigo = botao.closest("article");

                                                                                                                                                                                                                                          if (!artigo) return;

                                                                                                                                                                                                                                              const contador = artigo.querySelector(".contador-curtidas");

                                                                                                                                                                                                                                                  if (!contador) return;

                                                                                                                                                                                                                                                      let curtidas = Number(contador.textContent) || 0;
                                                                                                                                                                                                                                                          curtidas++;

                                                                                                                                                                                                                                                              contador.textContent = curtidas;
                                                                                                                                                                                                                                                                  botao.textContent = "❤️ Curtido!";
                                                                                                                                                                                                                                                                      botao.disabled = true;
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                      // 9. Compartilhar o blog
                                                                                                                                                                                                                                                                      async function compartilharBlog() {
                                                                                                                                                                                                                                                                          const dados = {
                                                                                                                                                                                                                                                                                  title: document.title,
                                                                                                                                                                                                                                                                                          text: "Confira este blog!",
                                                                                                                                                                                                                                                                                                  url: window.location.href
                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                                                  if (navigator.share) {
                                                                                                                                                                                                                                                                                                                              await navigator.share(dados);
                                                                                                                                                                                                                                                                                                                                      } else if (navigator.clipboard) {
                                                                                                                                                                                                                                                                                                                                                  await navigator.clipboard.writeText(dados.url);
                                                                                                                                                                                                                                                                                                                                                              alert("Link copiado! Compartilhe com seus amigos.");
                                                                                                                                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                                                                                                                                                  alert("Copie o endereço do site para compartilhar.");
                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                              } catch (erro) {
                                                                                                                                                                                                                                                                                                                                                                                                      if (erro.name !== "AbortError") {
                                                                                                                                                                                                                                                                                                                                                                                                                  alert("Não foi possível compartilhar agora.");
                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                              // 10. Adicionar comentário na página
                                                                                                                                                                                                                                                                                                                                                                                                                              function adicionarComentario() {
                                                                                                                                                                                                                                                                                                                                                                                                                                  const campo = document.getElementById("comentario");
                                                                                                                                                                                                                                                                                                                                                                                                                                      const lista = document.getElementById("lista-comentarios");

                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!campo || !lista) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                              const texto = campo.value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (texto.length < 2) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                          alert("Escreva um comentário antes de enviar.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (texto.length > 500) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  alert("O comentário deve ter até 500 caracteres.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const novoComentario = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      novoComentario.className = "comentario";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          novoComentario.textContent = texto;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              lista.prepend(novoComentario);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  campo.value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 11. Contar caracteres do comentário
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function contarCaracteres() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const campo = document.getElementById("comentario");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const contador = document.getElementById("total-caracteres");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (campo && contador) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      contador.textContent = campo.value.length + "/500";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 12. Mostrar ou esconder um conteúdo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function alternarConteudo(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const elemento = document.getElementById(id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!elemento) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const escondido = getComputedStyle(elemento).display === "none";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          elemento.style.display = escondido ? "block" : "none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 13. Voltar ao topo da página
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function voltarAoTopo() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              window.scrollTo({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      top: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              behavior: "smooth"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 14. Mostrar botão de voltar ao topo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function controlarBotaoTopo() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const botao = document.getElementById("botao-topo");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (botao) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  botao.style.display =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              window.scrollY > 300 ? "block" : "none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 15. Validar formulário de contato
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function validarContato(evento) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      evento.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const nome = document.getElementById("nome");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const email = document.getElementById("email");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const mensagem = document.getElementById("mensagem");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!nome || !email || !mensagem) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  !nome.value.trim() ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          !email.value.trim() ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  !mensagem.value.trim()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              alert("Preencha todos os campos!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!email.validity.valid) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      alert("Digite um endereço de e-mail válido.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      alert("Formulário validado! Para enviar de verdade, conecte um servidor ou serviço de formulários.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // 16. Mostrar quantidade de artigos
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function contarArtigos() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const resultado = document.getElementById("total-artigos");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (resultado) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const artigos = document.querySelectorAll("article");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              resultado.textContent = artigos.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 17. Animação simples ao aparecer na tela
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function animarElementos() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const elementos = document.querySelectorAll(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "article, .destaque, .sobre"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!("IntersectionObserver" in window)) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const observador = new IntersectionObserver(function(entradas) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  entradas.forEach(function(entrada) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (entrada.isIntersecting) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              entrada.target.classList.add("visivel");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              observador.unobserve(entrada.target);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              threshold: 0.15
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      elementos.forEach(function(elemento) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              observador.observe(elemento);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 18. Atualizar o ano automaticamente
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function atualizarAno() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const elemento = document.getElementById("ano");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (elemento) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  elemento.textContent = new Date().getFullYear();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // 19. Mostrar aviso ao sair da pesquisa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function prepararPesquisa() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const campo = document.getElementById("pesquisa");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (campo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      campo.addEventListener("input", pesquisarArtigos);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 20. Inicializar as funções do blog
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.addEventListener("DOMContentLoaded", function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              carregarTema();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  mostrarData();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      atualizarRelogio();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          contarArtigos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              atualizarAno();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  prepararPesquisa();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      animarElementos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Atualiza o relógio a cada segundo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setInterval(atualizarRelogio, 1000);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Verifica a posição da página ao rolar
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      window.addEventListener("scroll", controlarBotaoTopo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          controlarBotaoTopo();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.log("✅ Meu Blog foi carregado com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
